{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if nodes is None or required_symbols is None:
        raise ValueError("missing nodes or required_symbols")
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("nodes and required_symbols must be lists")
    node_map = {}
    children = {}
    root_id = None
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be dict")
        for key in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if key not in node:
                raise ValueError(f"node missing '{key}'")
        nid = node['id']
        if nid in node_map:
            raise ValueError(f"duplicate node id {nid}")
        node_map[nid] = node
        children[nid] = []
    for nid, node in node_map.items():
        parent = node['parent']
        if parent is None:
            if root_id is not None:
                raise ValueError("multiple roots")
            root_id = nid
        else:
            if parent not in node_map:
                raise ValueError(f"parent {parent} not found")
            children[parent].append(nid)
    if root_id is None:
        raise ValueError("no root node (parent null)")
    symbol_counts = {}
    for node in node_map.values():
        sym = node['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
    sorted_nodes = sorted(node_map.values(), key=lambda n: (-n['depth'], n['id']))
    removed = set()
    removal_order = []
    for node in sorted_nodes:
        nid = node['id']
        if nid == root_id:
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols:
            continue
        has_retained_children = any(child_id not in removed for child_id in children.get(nid, []))
        if has_retained_children:
            continue
        can_remove = True
        for sym in required_symbols:
            count = symbol_counts[sym]
            if sym == node['symbol']:
                count -= 1
            if count < 1:
                can_remove = False
                break
        if not can_remove:
            continue
        removed.add(nid)
        removal_order.append(nid)
        symbol_counts[node['symbol']] -= 1
    retained_ids = sorted(nid for nid in node_map if nid not in removed)
    return {"removed_node_ids": removal_order, "retained_node_ids": retained_ids}"}
